//! Immutable world description handed to the client once, at boot.
//!
//! The planet is generated deterministically from the seed inside the
//! simulation, but it is **not** shipped as a tile array: 10240 x 10240 tiles is
//! a gigabyte of bytes on the wire. The boot blob carries only the planet's
//! dimensions, its chunk size and the colony anchor; terrain arrives per 32x32
//! chunk through [`ChunkView`] (`oc_chunk` on the bridge), generated by the same
//! pure function the simulation queries.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

use crate::Catalog;

/// The planet's dimensions and seed.
#[derive(Clone, Debug, Default, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../../web/src/generated/")]
pub struct MapView {
    /// World seed the client may echo; terrain is fetched per chunk.
    pub seed: u32,
    /// Planet circumference along x, in tiles.
    pub width: u16,
    /// Planet circumference along y, in tiles.
    pub height: u16,
    /// Chunk edge in tiles (`ChunkView` arrays are `chunk_size^2` long).
    pub chunk_size: u16,
    /// Colony anchor tile x, so the camera can start on the colony.
    pub start_tx: u16,
    /// Colony anchor tile y.
    pub start_ty: u16,
    /// Guided regional oilfield anchor x.
    pub oil_tx: u16,
    /// Guided regional oilfield anchor y.
    pub oil_ty: u16,
}

/// One 32x32 chunk of the planet surface.
///
/// Row-major, `chunk_size * chunk_size` entries per array. Coordinates wrap, so
/// `cx = -1` and `cx = 319` name the same chunk.
#[derive(Clone, Debug, Default, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../../web/src/generated/")]
pub struct ChunkView {
    /// Chunk column, `0..width / chunk_size`.
    pub cx: i32,
    /// Chunk row, `0..height / chunk_size`.
    pub cy: i32,
    /// Terrain material index per tile (`T_*` in `oc-content`).
    pub terrain: Vec<u8>,
    /// Decoration index per tile (`D_*` in `oc-content`), `0` = bare.
    pub decor: Vec<u8>,
    /// Elevation step: `-2` deep water, `-1` shallow water, `0..=3` land.
    pub elev: Vec<i8>,
    /// Mineral richness, `0` = none. Refineries must sit on ore.
    pub ore: Vec<u8>,
    /// Coal seam richness, `0` = none. Coal extractors must sit on a seam.
    pub coal: Vec<u8>,
    /// Oil reservoir richness, `0` = none. Oil wells must sit on a reservoir.
    pub oil: Vec<u8>,
}

/// Everything the client needs before the first tick.
#[derive(Clone, Debug, Default, Serialize, Deserialize, TS)]
#[ts(export, export_to = "../../../web/src/generated/")]
pub struct BootBlob {
    /// Protocol version; the client refuses a mismatch.
    pub protocol: u16,
    /// World seed, echoed so the HUD can print the run id.
    pub seed: u32,
    /// Static content tables.
    pub catalog: Catalog,
    /// The planet's dimensions, chunk size and colony anchor.
    pub map: MapView,
}
